def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    pts = [(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != bg]
    for r,c,v in pts:
        for dr in (-1,1):
            for dc in (-1,1):
                rr,cc=r+dr,c+dc
                if 0<=rr<h and 0<=cc<w and grid[rr][cc]==v:
                    # Color rays outwards from the adjacent equal-color pair.
                    x,y=r-dr,c-dc
                    while 0<=x<h and 0<=y<w and out[x][y]==bg:
                        out[x][y]=v; x-=dr; y-=dc
                    x,y=rr+dr,cc+dc
                    while 0<=x<h and 0<=y<w and out[x][y]==bg:
                        out[x][y]=v; x+=dr; y+=dc
    return out

